public class Lesson {
    static int damageAfterArmor(int rawDamage, int armorPoints) {
        int reduced = rawDamage - armorPoints / 2;
        return Math.max(reduced, 0);
    }

    public static void main(String[] args) {
        System.out.println(damageAfterArmor(10, 4));
        System.out.println(damageAfterArmor(10, 30));
    }
}
